@charset "UTF-8";
/* Reset e base */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.custom-table-wrapper {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  width: 100%;
  height: 100%;
  background: #f8f9fa;
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
}

/* Header */
.header-info {
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
  padding: clamp(1rem, 3vw, 1.5rem) clamp(1rem, 4vw, 2rem);
  border-radius: 12px;
  margin: clamp(0.5rem, 2vw, 1rem);
  margin-bottom: clamp(0.5rem, 1vw, 0.75rem);
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.1);
  flex-shrink: 0;
  z-index: 100;
}

.header-title {
  font-size: clamp(1rem, 3vw, 1.5rem);
  font-weight: 600;
  line-height: 1.4;
  text-align: center;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.2);
  word-wrap: break-word;
  hyphens: auto;
}

.header-title .highlight {
  background: rgba(255, 255, 255, 0.2);
  padding: 0.2rem 0.5rem;
  border-radius: 6px;
  font-weight: 700;
  margin: 0 0.2rem;
  display: inline-block;
}

/* Indicatore di progresso */
.progress-indicator {
  background: white;
  padding: clamp(0.75rem, 2vw, 1rem) clamp(1rem, 3vw, 2rem);
  margin: 0 clamp(0.5rem, 2vw, 1rem) clamp(0.5rem, 1vw, 0.75rem);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: clamp(0.5rem, 2vw, 1rem);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
  border: 1px solid #e9ecef;
  font-size: clamp(0.8rem, 2vw, 0.95rem);
  font-weight: 500;
  flex-shrink: 0;
}

.progress-indicator span {
  white-space: nowrap;
  text-align: center;
  min-width: 0;
}

.validation-summary {
  color: #dc3545;
  font-weight: 600;
  background: #f8d7da;
  padding: 0.5rem 1rem;
  border-radius: 6px;
  border: 1px solid #f5c6cb;
  text-align: center;
  width: 100%;
}

/* Contenitore tabella */
.table-container {
  flex: 1;
  margin: 0 clamp(0.5rem, 2vw, 1rem);
  background: white;
  border-radius: 8px;
  overflow: auto;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.08);
  border: 1px solid #e9ecef;
  min-height: 0;
}

/* Tabella */
.detail-table {
  width: 100%;
  border-collapse: collapse;
  font-size: clamp(0.8rem, 2vw, 0.95rem);
  table-layout: fixed;
}

.detail-table th {
  background: #f8f9fa;
  padding: clamp(0.75rem, 2vw, 1rem) clamp(1rem, 3vw, 1.5rem);
  text-align: left;
  font-weight: 600;
  color: #495057;
  border-bottom: 2px solid #dee2e6;
  width: clamp(120px, 30%, 200px);
  vertical-align: middle;
  position: relative;
  word-wrap: break-word;
  hyphens: auto;
}

.detail-table td {
  padding: clamp(0.75rem, 2vw, 1rem) clamp(1rem, 3vw, 1.5rem);
  border-bottom: 1px solid #e9ecef;
  vertical-align: middle;
  word-wrap: break-word;
  overflow-wrap: break-word;
}

.detail-table tr:hover {
  background: #f8f9fa;
}

.detail-table tr.error-row {
  background: #fff5f5;
  border-left: 4px solid #dc3545;
}

.detail-table tr.error-row th {
  background: #fff5f5;
  color: #dc3545;
}

/* Indicatore campo obbligatorio */
.required-indicator {
  color: #dc3545;
  font-weight: bold;
  margin-left: 0.3rem;
  font-size: 1.1rem;
}

/* Textarea per note */
textarea {
  width: 100%;
  padding: 0.75rem;
  border: 2px solid #e9ecef;
  border-radius: 6px;
  font-family: inherit;
  font-size: clamp(0.8rem, 2vw, 0.9rem);
  resize: vertical;
  min-height: clamp(50px, 10vw, 60px);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
  box-sizing: border-box;
}

textarea:focus {
  outline: none;
  border-color: #007bff;
  box-shadow: 0 0 0 3px rgba(0, 123, 255, 0.1);
}

textarea.error {
  border-color: #dc3545;
  background: #fff5f5;
}

textarea.error:focus {
  border-color: #dc3545;
  box-shadow: 0 0 0 3px rgba(220, 53, 69, 0.1);
}

/* Sistema di rating a stelle */
.star-rating {
  display: flex;
  align-items: center;
  gap: clamp(0.2rem, 1vw, 0.3rem);
  padding: 0.5rem 0;
  flex-wrap: wrap;
  justify-content: flex-start;
}

.star-rating.error {
  background: #fff5f5;
  border-radius: 6px;
  padding: 0.5rem;
  border: 2px solid #dc3545;
}

.star {
  font-size: clamp(1.2rem, 4vw, 1.8rem);
  color: #ffc107;
  cursor: pointer;
  transition: all 0.2s ease;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.1);
  user-select: none;
  line-height: 1;
  touch-action: manipulation;
}

.star:hover {
  transform: scale(1.1);
  filter: brightness(1.2);
}

.star.inactive {
  color: #dee2e6;
  text-shadow: none;
}

.star.hovered {
  transform: scale(1.2);
  filter: brightness(1.3) drop-shadow(0 2px 4px rgba(255, 193, 7, 0.4));
}

/* Nuovi stili per le stelle colorate in base al valore (4 stelle) */
.star-rating.rating-1 .star:not(.inactive) {
  color: #dc3545; /* Rosso per 1 stella */
}

.star-rating.rating-2 .star:not(.inactive) {
  color: #fd7e14; /* Arancione per 2 stelle */
}

.star-rating.rating-3 .star:not(.inactive),
.star-rating.rating-4 .star:not(.inactive) {
  color: #28a745; /* Verde per 3-4 stelle */
}

/* Effetti hover per i diversi colori */
.star-rating.rating-1 .star:not(.inactive):hover {
  filter: brightness(1.2);
  color: #dc3545;
}

.star-rating.rating-2 .star:not(.inactive):hover {
  filter: brightness(1.2);
  color: #fd7e14;
}

.star-rating.rating-3 .star:not(.inactive):hover,
.star-rating.rating-4 .star:not(.inactive):hover {
  filter: brightness(1.2);
  color: #28a745;
}

/* Effetti hovered per i diversi colori */
.star-rating.rating-1 .star.hovered {
  color: #dc3545;
  filter: brightness(1.3) drop-shadow(0 2px 4px rgba(220, 53, 69, 0.4));
}

.star-rating.rating-2 .star.hovered {
  color: #fd7e14;
  filter: brightness(1.3) drop-shadow(0 2px 4px rgba(253, 126, 20, 0.4));
}

.star-rating.rating-3 .star.hovered,
.star-rating.rating-4 .star.hovered {
  color: #28a745;
  filter: brightness(1.3) drop-shadow(0 2px 4px rgba(40, 167, 69, 0.4));
}

/* Stili per il testo descrittivo */
.rating-description {
  margin-left: clamp(0.5rem, 2vw, 1rem);
  font-size: clamp(0.75rem, 2vw, 0.9rem);
  font-weight: 600;
  padding: 0.25rem 0.75rem;
  border-radius: 20px;
  background: #f8f9fa;
  border: 1px solid #dee2e6;
  color: #495057;
  transition: all 0.2s ease;
  white-space: nowrap;
  flex-shrink: 0;
}

/* Colori del testo descrittivo in base al rating (4 stelle) */
.star-rating.rating-1 .rating-description {
  background: #f8d7da;
  border-color: #f5c6cb;
  color: #721c24;
}

.star-rating.rating-2 .rating-description {
  background: #fff3cd;
  border-color: #ffeaa7;
  color: #856404;
}

.star-rating.rating-3 .rating-description,
.star-rating.rating-4 .rating-description {
  background: #d4edda;
  border-color: #c3e6cb;
  color: #155724;
}

.error-text {
  color: #dc3545;
  font-size: clamp(0.7rem, 2vw, 0.8rem);
  margin-left: 0.5rem;
  font-weight: 500;
}

/* Contenitore dei pulsanti - FISSO AL FONDO */
.button-container {
  display: flex;
  gap: clamp(0.5rem, 2vw, 1rem);
  margin: clamp(0.5rem, 1vw, 0.75rem) clamp(0.5rem, 2vw, 1rem) clamp(0.5rem, 2vw, 1rem);
  flex-wrap: wrap;
  justify-content: center;
  flex-shrink: 0;
  margin-top: auto;
}

/* Pulsante PDF */
.button-pdf {
  background: linear-gradient(135deg, #007bff 0%, #0056b3 100%);
  color: white;
  border: none;
  padding: clamp(0.75rem, 2vw, 1rem) clamp(1rem, 3vw, 2rem);
  font-size: clamp(0.9rem, 2vw, 1.1rem);
  font-weight: 600;
  border-radius: 8px;
  cursor: pointer;
  box-shadow: 0 4px 12px rgba(0, 123, 255, 0.3);
  transition: all 0.2s ease;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex: 1;
  justify-content: center;
  min-width: clamp(150px, 30vw, 200px);
  touch-action: manipulation;
}

.button-pdf:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(0, 123, 255, 0.4);
}

.button-pdf:active {
  transform: translateY(0);
}

/* Pulsante di invio */
.button-salva {
  background: linear-gradient(135deg, #28a745 0%, #20c997 100%);
  color: white;
  border: none;
  padding: clamp(0.75rem, 2vw, 1rem) clamp(1rem, 3vw, 2rem);
  font-size: clamp(0.9rem, 2vw, 1.1rem);
  font-weight: 600;
  border-radius: 8px;
  cursor: pointer;
  box-shadow: 0 4px 12px rgba(40, 167, 69, 0.3);
  transition: all 0.2s ease;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  flex: 1;
  min-width: clamp(150px, 30vw, 200px);
  touch-action: manipulation;
}

.button-salva:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(40, 167, 69, 0.4);
}

.button-salva:active {
  transform: translateY(0);
}

.button-salva:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none;
}

.button-salva.error {
  background: linear-gradient(135deg, #dc3545 0%, #c82333 100%);
  box-shadow: 0 4px 12px rgba(220, 53, 69, 0.3);
}

.button-salva.error:hover:not(:disabled) {
  box-shadow: 0 6px 16px rgba(220, 53, 69, 0.4);
}

/* Animazioni */
@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.detail-table tr {
  animation: fadeIn 0.3s ease forwards;
}

.detail-table tr:nth-child(even) {
  animation-delay: 0.05s;
}

.detail-table tr:nth-child(odd) {
  animation-delay: 0.1s;
}

/* Breakpoint per tablet */
@media (max-width: 1024px) {
  .detail-table th {
    width: 35%;
  }
  .star-rating {
    flex-direction: row;
    flex-wrap: wrap;
    justify-content: flex-start;
  }
  .rating-description {
    margin-left: 0.5rem;
    margin-top: 0.25rem;
  }
}
/* Breakpoint per smartphone */
@media (max-width: 768px) {
  .header-info {
    margin: 0.5rem 0.5rem 0.5rem 0.5rem;
    padding: 1rem;
  }
  .progress-indicator {
    flex-direction: column;
    gap: 0.5rem;
    margin: 0 0.5rem 0.5rem 0.5rem;
    padding: 1rem;
    text-align: center;
  }
  .progress-indicator span {
    width: 100%;
  }
  .table-container {
    margin: 0 0.5rem;
  }
  .detail-table th {
    width: 40%;
    padding: 0.75rem 0.5rem;
  }
  .detail-table td {
    padding: 0.75rem 0.5rem;
  }
  .button-container {
    flex-direction: column;
    margin: 0.5rem 0.5rem 0.5rem 0.5rem;
    gap: 0.5rem;
  }
  .button-pdf,
  .button-invia {
    min-width: auto;
    width: 100%;
  }
  .star-rating {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.5rem;
  }
  .rating-description {
    margin-left: 0;
    margin-top: 0.5rem;
    font-size: 0.8rem;
    padding: 0.2rem 0.5rem;
  }
}
/* Breakpoint per smartphone piccoli */
@media (max-width: 480px) {
  .header-title {
    font-size: 0.9rem;
    line-height: 1.2;
  }
  .progress-indicator {
    font-size: 0.75rem;
    padding: 0.75rem;
  }
  .detail-table {
    font-size: 0.8rem;
  }
  .detail-table th,
  .detail-table td {
    padding: 0.5rem 0.25rem;
  }
  .detail-table th {
    width: 45%;
  }
  .star {
    font-size: 1.2rem;
  }
  .rating-description {
    font-size: 0.7rem;
    padding: 0.15rem 0.4rem;
  }
  .button-pdf,
  .button-invia {
    padding: 0.75rem 1rem;
    font-size: 0.9rem;
  }
  .validation-summary {
    font-size: 0.8rem;
    padding: 0.4rem 0.8rem;
  }
}
/* Breakpoint per schermi molto piccoli */
@media (max-width: 320px) {
  .header-title {
    font-size: 0.8rem;
  }
  .progress-indicator {
    font-size: 0.7rem;
    padding: 0.5rem;
  }
  .detail-table th,
  .detail-table td {
    padding: 0.4rem 0.2rem;
  }
  .star {
    font-size: 1rem;
  }
  .rating-description {
    font-size: 0.65rem;
  }
}
/* Orientamento landscape per mobile */
@media (max-width: 768px) and (orientation: landscape) {
  .custom-table-wrapper {
    height: 100vh;
  }
  .header-info {
    position: relative;
    margin: 0.25rem;
    padding: 0.5rem 1rem;
  }
  .progress-indicator {
    flex-direction: row;
    flex-wrap: wrap;
    justify-content: center;
    margin: 0.25rem 0.5rem;
    padding: 0.5rem;
  }
  .button-container {
    flex-direction: row;
    margin: 0.25rem 0.5rem 0.5rem 0.5rem;
  }
}
/* Miglioramenti per l'accessibilità */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
/* Focus per navigazione con tastiera */
.star:focus,
textarea:focus,
.button-invia:focus,
.button-pdf:focus {
  outline: 2px solid #007bff;
  outline-offset: 2px;
}

/* Miglioramenti per dispositivi touch */
@media (hover: none) and (pointer: coarse) {
  .star:hover {
    transform: none;
    filter: none;
  }
  .star:active {
    transform: scale(0.95);
  }
  .button-pdf:hover,
  .button-invia:hover {
    transform: none;
  }
  .button-pdf:active,
  .button-invia:active {
    transform: scale(0.98);
  }
}
/* Stato di caricamento */
.button-invia:disabled {
  position: relative;
  overflow: hidden;
}

.button-invia:disabled::after {
  content: "";
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.2), transparent);
  animation: loading 1.5s infinite;
}

@keyframes loading {
  0% {
    left: -100%;
  }
  100% {
    left: 100%;
  }
}
/* Scrollbar personalizzata */
.table-container::-webkit-scrollbar {
  width: 8px;
}

.table-container::-webkit-scrollbar-track {
  background: #f1f1f1;
  border-radius: 4px;
}

.table-container::-webkit-scrollbar-thumb {
  background: #c1c1c1;
  border-radius: 4px;
}

.table-container::-webkit-scrollbar-thumb:hover {
  background: #a8a8a8;
}

/* Supporto per schermi ad alta densità */
@media (-webkit-min-device-pixel-ratio: 2), (min-resolution: 192dpi) {
  .star {
    text-rendering: optimizeLegibility;
  }
}

