  }

  .star-rating {
    flex-direction: row;
    flex-wrap: wrap;
    justify-content: flex-start;
  }

  .rating-description {
    margin-left: 0.5rem;
    margin-top: 0.25rem;
  }
}

/* Breakpoint per smartphone */
@media (max-width: 768px) {
  .header-info {
    margin: 0.5rem 0.5rem 0.5rem 0.5rem;
