  }

  .detail-table th {
    width: 40%;
    padding: 0.75rem 0.5rem;
  }

  .detail-table td {
    padding: 0.75rem 0.5rem;
  }

  .button-container {
    flex-direction: column;
    margin: 0.5rem 0.5rem 0.5rem 0.5rem;
    gap: 0.5rem;
  }

  .button-pdf,
  .button-invia {
    min-width: auto;
    width: 100%;
  }

  .star-rating {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.5rem;
  }

  .rating-description {
    margin-left: 0;
    margin-top: 0.5rem;
    font-size: 0.8rem;
    padding: 0.2rem 0.5rem;
