  .button-invia {
    padding: 0.75rem 1rem;
    font-size: 0.9rem;
  }

  .validation-summary {
    font-size: 0.8rem;
    padding: 0.4rem 0.8rem;
  }
}

/* Breakpoint per schermi molto piccoli */
@media (max-width: 320px) {
  .header-title {
    font-size: 0.8rem;
  }

  .progress-indicator {
    font-size: 0.7rem;
    padding: 0.5rem;
  }

  .detail-table th,
