/**
 * Parser robusto che recupera dati anche da strutture:
 *  - stringa JSON valida
 *  - { data: "<JSON NON ESCAPATO>" }
 *  - { data: "{\"JSON ESCAPATO\"}" }
 * Logga riparazioni eseguite.
 */
function safeParse(root) {
  const logNS = "[DettaglioSettimanaWidget::parse]";
  const cloneLog = (msg, extra) => {
    try { console.log(logNS, msg, extra || ''); } catch {}
  };

  function tryJSON(str) {
    try {
      return JSON.parse(str);
    } catch (e) {
      return { __error: e };
    }
  }

  function repairDataContainerString(raw) {
    // Caso: "data":"{...}" con interno non escapato → sostituisco "data":"{...}" -> "data":{...}
    const repaired = raw.replace(/"data":"(\{[\s\S]*\})"/, (m, inner) => {
      cloneLog("Riparazione pattern data non escapato");
      return `"data":${inner}`;
    }).replace(/"edited":"(\{[\s\S]*\})"/, (m, inner) => {
      cloneLog("Riparazione pattern edited non escapato");
      return `"edited":${inner}`;
    });
    return repaired;
  }

  function deepSanitize(obj) {
    if (!obj || typeof obj !== 'object') return obj;
    const out = Array.isArray(obj) ? [] : {};
    Object.entries(obj).forEach(([k,v]) => {
      if (typeof v === 'string') {
        // Rimuove caratteri di controllo invisibili (eccetto tab, lf, cr)
        const cleaned = v.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g, '')
                         .replace(/[""«»]/g, '"')
                         .replace(/['']/g, "'");
        out[k] = cleaned;
      } else if (v && typeof v === 'object') {
        out[k] = deepSanitize(v);
      } else {
        out[k] = v;
      }
    });
    return out;
  }

  // Caso 1: già oggetto utilizzabile
  if (root && typeof root === 'object' && !root.error) {
    if (root.data && typeof root.data === 'string') {
      const p = tryJSON(root.data);
      if (!p.__error && typeof p === 'object') {
        return deepSanitize(p);
      }
    }
    return deepSanitize(root);
  }

  if (typeof root !== 'string') return root;

  // Primo tentativo
  let first = tryJSON(root);
  if (!first.__error) {
    if (first && typeof first === 'object' && typeof first.data === 'string') {
      const inner = tryJSON(first.data);
      if (!inner.__error) return deepSanitize(inner);
    }
    return deepSanitize(first);
  }

  cloneLog("Prima parse fallita, tento riparazione euristica");
  const repairedOnce = repairDataContainerString(root);
  if (repairedOnce !== root) {
    const second = tryJSON(repairedOnce);
    if (!second.__error) {
      if (second && typeof second === 'object' && second.data && typeof second.data === 'object') {
        return deepSanitize(second.data);
      }
      return deepSanitize(second);
    }
  }

  // Tentativo pseudo-JSON con apici singoli
  const pseudo = root
    .replace(/([{,]\s*)'([^'"]+?)'\s*:/g, '$1"$2":')
    .replace(/:\s*'([^'"]*?)'/g, (m,g1) => ': "' + g1.replace(/"/g, '\\"') + '"');

