        const inner = tryJSON(third.data);
        if (!inner.__error) return deepSanitize(inner);
      }
      return deepSanitize(third);
    }
  }

  cloneLog("Impossibile parsare i dati dopo i tentativi", { raw: root });
  return {};
}

function parseData(obj) {
  return safeParse(obj);
}

function StarRating({ value = 0, onChange, isRequired = false, hasError = false }) {
  const [hoveredStar, setHoveredStar] = React.useState(0);
  const [isMobile, setIsMobile] = React.useState(false);

  React.useEffect(() => {
    const checkMobile = () => setIsMobile(window.innerWidth <= 768);
    checkMobile();
    window.addEventListener('resize', checkMobile);
    return () => window.removeEventListener('resize', checkMobile);
  }, []);

  const ratingTexts = {
    1: "Non lo sa fare",
    2: "Sta ancora imparando",
    3: "Lo sa fare",
    4: "Lo sa insegnare"
  };

  const getRatingClass = (currentValue) =>
    currentValue ? `rating-${currentValue}` : '';

  const displayValue = hoveredStar > 0 ? hoveredStar : value;

  const handleStarClick = (star) => {
    onChange(star);
    if (isMobile) {
      setHoveredStar(star);
      setTimeout(() => setHoveredStar(0), 300);
    }
  };

  return (
    <div
      className={`star-rating ${hasError ? 'error' : ''} ${getRatingClass(displayValue)}`}
      onMouseLeave={() => !isMobile && setHoveredStar(0)}
    >
      {[1,2,3,4].map(star => {
        const isHighlighted = hoveredStar > 0 ? star <= hoveredStar : star <= value;
        const isHovered = hoveredStar > 0 && star === hoveredStar;
        return (
          <span
            key={star}
            className={`star ${!isHighlighted ? 'inactive' : ''} ${isHovered ? 'hovered' : ''}`}
            onClick={() => handleStarClick(star)}
            onMouseEnter={() => !isMobile && setHoveredStar(star)}
            onTouchStart={() => isMobile && setHoveredStar(star)}
            title={`Valuta ${star}/4`}
            role="button"
            tabIndex={0}
            aria-label={`Valutazione ${star} su 4: ${ratingTexts[star]}`}
          >
            ★
          </span>
        );
      })}
      {isRequired && <span className="required-indicator">*</span>}
      {hasError && <span className="error-text">Campo obbligatorio</span>}
      {displayValue > 0 && (
        <span className="rating-description">
          {ratingTexts[displayValue]}
        </span>
      )}
    </div>
  );
}

function HeaderInfo({ data }) {
  const [isSmallScreen, setIsSmallScreen] = React.useState(false);
  React.useEffect(() => {
    const check = () => setIsSmallScreen(window.innerWidth <= 480);
    check();
    window.addEventListener('resize', check);
    return () => window.removeEventListener('resize', check);
  }, []);

  const formatDate = (d) => {
    if (!d) return 'N/A';
    try {
      const date = new Date(d);
      return date.toLocaleDateString('it-IT', {
        day: '2-digit',
        month: '2-digit',
        year: isSmallScreen ? '2-digit' : 'numeric'
      });
    } catch {
      return 'N/A';
    }
  };

  const nome = data.Nome || 'N/A';
  const neg = data.Neg || 'N/A';
  const dataAssunzione = data.DataAssunzione || null;
  const dataFineContratto = data.DataFineContratto || null;

  const detectCategory = (data) => {
    for (let i=1;i<=4;i++) {
      if (Object.keys(data).some(k => k.startsWith(i.toString()))) return i;
    }
    return 1;
  };
  const currentCategory = detectCategory(data);

  if (isSmallScreen) {
    return (
      <div className="header-info">
        <h2 className="header-title">
          <span className="highlight">{currentCategory}°</span> Settimana
          <br />
            <span className="highlight">{nome}</span>
          <br />
          <small>{neg} • {formatDate(dataAssunzione)} - {formatDate(dataFineContratto)}</small>
        </h2>
      </div>
    );
  }

  return (
    <div className="header-info">
      <h2 className="header-title">
        <span className="highlight">{currentCategory}°</span>
        Settimana di <span className="highlight">{nome}</span> assunta su <span className="highlight">{neg}</span> il <span className="highlight">{formatDate(dataAssunzione)}</span> con scadenza al <span className="highlight">{formatDate(dataFineContratto)}</span>
      </h2>
    </div>
  );
}

function DetailsTable({
  fields,
  onFieldChange,
  editingNotes,
  onNoteFocus,
  onNoteChange,
  onNoteBlur,
  validationErrors
}) {

  function isRequiredField(key) {
    return /^[1234](?!.*Note).*/i.test(key);
  }
  function isHiddenField(key) {
    return key === 'IdSettimane';
  }
  function formatColumnName(key) {
    let processed = key;
    if (/^[0-9]/.test(key)) processed = key.substring(1);
    return processed.replace(/([A-Z])/g, (m,l,i) => i === 0 ? l : ' ' + l);
  }
  function formatDateValue(value) {
    if (!value || typeof value !== 'string') return value;
    if (/^\d{4}-\d{2}-\d{2}$/.test(value)) {
      const [y,m,d] = value.split('-');
      return `${d}/${m}/${y}`;
    }
    return value;
  }
  function formatNoteValue(value) {
    if (value === null || value === undefined || value === 'null') return '';
    return String(value);
  }

  function sanitizeInput(text) {
    if (typeof text !== 'string') return text;
    return text
      .replace(/[""«»]/g, '"')
      .replace(/['']/g, "'")
      .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g, '');
  }

  function renderInput(key, value) {
    const noteMatch = /^[1234].*Note.*/i.test(key);
    const scoreMatch = /^[1234](?!.*Note).*/i.test(key);
    const isRequired = isRequiredField(key);
    const hasError = validationErrors.includes(key);

    if (noteMatch) {
      const noteValue = formatNoteValue(value);
      const editingValue = key in editingNotes ? editingNotes[key] : noteValue;
      return (
        <textarea
          value={editingValue}
          onFocus={() => onNoteFocus(key)}
          onChange={e => onNoteChange(key, sanitizeInput(e.target.value))}
          onBlur={() => onNoteBlur(key)}
          rows={2}
          placeholder="Scrivi una nota..."
          autoFocus={false}
          className={hasError ? 'error' : ''}
        />
      );
    } else if (scoreMatch) {
      return (
        <StarRating
          value={parseInt(value) || 0}
            onChange={val => onFieldChange(key, val)}
          isRequired={isRequired}
          hasError={hasError}
        />
      );
    } else {
      const formattedValue = formatDateValue(value);
      return <span>{String(formattedValue ?? "")}</span>;
    }
  }

  return (
    <table className="detail-table">
      <tbody>
        {Object.entries(fields)
          .filter(([key]) => !isHiddenField(key))
          .map(([key, value]) => {
            const isRequired = isRequiredField(key);
            const hasError = validationErrors.includes(key);
            return (
              <tr key={key} data-field={key} className={hasError ? 'error-row' : ''}>
                <th>
                  {formatColumnName(key)}
                  {isRequired && <span className="required-indicator">*</span>}
                </th>
                <td>{renderInput(key, value)}</td>
              </tr>
            );
          })}
      </tbody>
    </table>
  );
}

function App() {
  const [data, setData] = React.useState(() => parseData(appsmith.model.data));
  const [edited, setEdited] = React.useState({});
  const [editingNotes, setEditingNotes] = React.useState({});
  const [isSubmitting, setIsSubmitting] = React.useState(false);
  const [validationErrors, setValidationErrors] = React.useState([]);
  const [isPDFGenerating, setIsPDFGenerating] = React.useState(false);
  const [screenSize, setScreenSize] = React.useState('desktop');

  const containerRef = React.useRef(null);

  React.useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth <= 480) setScreenSize('mobile');
      else if (window.innerWidth <= 768) setScreenSize('tablet');
      else setScreenSize('desktop');
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  React.useEffect(() => {
    const parsedData = parseData(appsmith.model.data);
    setData(parsedData || {});
    setEdited({});
    setEditingNotes({});
    setValidationErrors([]);
  }, [appsmith.model.data]);

  function updateField(key, value) {
    const newEdited = { ...edited, [key]: value };
    setEdited(newEdited);
    if (value && validationErrors.includes(key)) {
      setValidationErrors(prev => prev.filter(e => e !== key));
    }

    // Manteniamo doppia serializzazione (richiesta)
    appsmith.updateModel({
      data: JSON.stringify(data),
      edited: JSON.stringify(newEdited),
      allData: { ...data, ...newEdited },
      isReady: true,
      version: 2
    });
  }

  function handleNoteFocus(key) {
    const currentValue = edited[key] || data[key];
    const formattedValue = (!currentValue || currentValue === 'null') ? '' : String(currentValue);
    setEditingNotes(old => ({ ...old, [key]: formattedValue }));
  }

  function handleNoteChange(key, value) {
    setEditingNotes(old => ({ ...old, [key]: value }));
  }

  function handleNoteBlur(key) {
    const noteValue = editingNotes[key] || '';
    updateField(key, noteValue);
    setEditingNotes(old => {
      const c = { ...old };
      delete c[key];
      return c;
    });
  }

  function validateForm() {
    const finalData = { ...data, ...edited };
    const errors = [];
    Object.keys(finalData).forEach(key => {
      if (/^[1234](?!.*Note).*/i.test(key)) {
        const v = finalData[key];
        if (!v || v === 0 || v === '0' || v === '') {
          errors.push(key);
        }
      }
    });
    return errors;
  }

  function scrollToFirstError(errors) {
    if (errors.length > 0 && containerRef.current) {
      const first = errors[0];
      const el = containerRef.current.querySelector(`[data-field="${first}"]`) ||
                 containerRef.current.querySelector('.error-row');
      if (el) {
        el.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }
    }
  }

  async function handlePDFDownload() {
    if (isPDFGenerating) return;
    setIsPDFGenerating(true);
    try {
      const finalData = { ...data, ...edited };
      if (!finalData || Object.keys(finalData).length === 0) {
        alert("Errore: Nessun dato disponibile per il download del PDF");
        return;
      }
      appsmith.updateModel({
        data: JSON.stringify(data),
        edited: JSON.stringify(edited),
        allData: finalData,
        isReady: true,
        lastAction: 'pdf_download',
        timestamp: new Date().toISOString(),
        userInfo: {
          username: appsmith?.user?.username || 'utente',
          generatedAt: new Date().toISOString()
        },
        version: 2
      });
      await appsmith.triggerEvent("onPDFDownload");
    } catch (e) {
      alert("Errore durante il download del PDF: " + e.message);
    } finally {
      setTimeout(() => setIsPDFGenerating(false), 1500);
    }
  }

  async function onInviaClick() {
    const errors = validateForm();
    if (errors.length > 0) {
      setValidationErrors(errors);
      const formatFieldName = (key) => {
        let p = key;
        if (/^[0-9]/.test(key)) p = key.substring(1);
        return p.replace(/([A-Z])/g, (m,l,i) => i === 0 ? l : ' ' + l);
      };
      const firstErrorFormatted = formatFieldName(errors[0]);
      alert(`Attenzione! Devi compilare tutti i campi obbligatori.\n\nIl primo campo mancante è: "${firstErrorFormatted}"\n\nTotale campi mancanti: ${errors.length}`);
      setTimeout(() => scrollToFirstError(errors), 100);
      return;
    }

    setIsSubmitting(true);
    setValidationErrors([]);
    try {
      const finalData = { ...data, ...edited };
      appsmith.updateModel({
        data: JSON.stringify(data),
        edited: JSON.stringify(edited),
        allData: finalData,
        isReady: true,
        lastAction: 'submit',
        timestamp: new Date().toISOString(),
        validationStatus: 'passed',
        userInfo: {
          username: appsmith?.user?.username || 'utente',
          submittedAt: new Date().toISOString()
        },
        version: 2
      });
      await new Promise(r => setTimeout(r, 80));
      await appsmith.triggerEvent("onInviaClick");
    } catch (e) {
      alert("Errore durante il salvataggio: " + e.message);
    } finally {
      setIsSubmitting(false);
    }
  }

  const displayValues = {};
  Object.keys(data || {}).forEach(k => {
    displayValues[k] = Object.prototype.hasOwnProperty.call(edited, k) ? edited[k] : data[k];
  });

  const requiredFields = Object.keys(data || {}).filter(k => /^[1234](?!.*Note).*/i.test(k));
  const completedFields = requiredFields.filter(k => {
    const v = displayValues[k];
    return v && v !== 0 && v !== '0' && v !== '';
  });

  const totalScore = requiredFields.reduce((sum, k) => {
    const val = parseInt(displayValues[k]) || 0;
    return sum + val;
  }, 0);

  const maxScore = requiredFields.length * 4;
  const halfMaxScore = (maxScore * 0.75) - 1; // lasciato come nel tuo codice

  let status, bgColor, textColor;
  if (totalScore === 0) {
    status = 'NON VALUTATO'; bgColor = '#FFA500'; textColor = '#FFFFFF';
  } else if (totalScore > halfMaxScore) {
    status = 'IDONEO'; bgColor = '#90EE90'; textColor = '#006400';
  } else {
    status = 'NON IDONEO'; bgColor = '#FF6B6B'; textColor = '#FFFFFF';
  }

  const completionPercentage = requiredFields.length > 0
    ? Math.round((completedFields.length / requiredFields.length) * 100)
    : 0;

  return (
    <div className="custom-table-wrapper" ref={containerRef}>
      <HeaderInfo data={data || {}} />
      <div className="progress-indicator">
        <span>Completati: {completedFields.length}/{requiredFields.length}</span>
        <span style={{
          marginLeft: screenSize === 'mobile' ? '0' : '20px',
          backgroundColor: bgColor,
          color: textColor,
          padding: '4px 8px',
          borderRadius: '4px',
          fontWeight: 'bold'
        }}>
          {status}
        </span>
        <span style={{ marginLeft: screenSize === 'mobile' ? '0' : '20px' }}>
          {screenSize === 'mobile' ? `${totalScore}/${maxScore}` : `Punteggio: ${totalScore}/${maxScore}`}
        </span>
        <span style={{ marginLeft: screenSize === 'mobile' ? '0' : '20px' }}>
          {completionPercentage}%
        </span>
        {validationErrors.length > 0 && (
          <span className="validation-summary">
            ⚠️ {validationErrors.length} campo/i da completare
          </span>
        )}
      </div>
      <div className="table-container">
        <DetailsTable
          fields={displayValues}
          onFieldChange={updateField}
          editingNotes={editingNotes}
          onNoteFocus={handleNoteFocus}
          onNoteChange={handleNoteChange}
          onNoteBlur={handleNoteBlur}
          validationErrors={validationErrors}
        />
      </div>
      <div className="button-container">
        <button
          className="button-pdf"
          onClick={handlePDFDownload}
          type="button"
          disabled={isPDFGenerating}
          title="Scarica la valutazione in formato PDF"
        >
          {isPDFGenerating ? "🔄 Generando..." : (screenSize === 'mobile' ? "📄 PDF" : "📄 Scarica Valutazione")}
        </button>
        <button
          className={`button-salva ${validationErrors.length > 0 ? 'error' : ''}`}
          onClick={onInviaClick}
          type="button"
          disabled={isSubmitting}
        >
          {isSubmitting ? "⏳ Salva..." : "✉️ Salva"}
        </button>
      </div>
    </div>
  );
}

function renderApp() {
  ReactDOM.render(<App />, document.getElementById("root"));
}

appsmith.onReady(() => {
  renderApp();
});

appsmith.onModelChange(() => {
  renderApp();
});
